refentry.refsect1:
&reftitle.description;
arrayarray_column arrayarray intstringnullcolumn_key intstringnullindex_key&null;
array_column returns the values from a single column of the array, identified by the column_key. Optionally, an index_key may be provided to index the values in the returned array by the values from the index_key column of the input array.
array is treated as a list of rows, each of which is itself an array or an object; a column is the entry or property that column_key names in every row. Rows that are neither an array nor an object, and rows in which that entry or property is absent, are skipped without a diagnostic. The keys of array are never preserved.

  &reftitle.examples;



    Get the column of first names from a recordset


<?php

// Array representing a possible record set returned from a database
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$first_names = array_column($records, 'first_name');
print_r($first_names);

?>


    &example.outputs;


Array
(
    [0] => John
    [1] => Sally
    [2] => Jane
    [3] => Peter
)








     Get the column of last names from a recordset, indexed by the "id" column



<?php

// Using the $records array from Example #1
$records = [
    [
        'id' => 2135,
        'first_name' => 'John',
        'last_name' => 'Doe',
    ],
    [
        'id' => 3245,
        'first_name' => 'Sally',
        'last_name' => 'Smith',
    ],
    [
        'id' => 5342,
        'first_name' => 'Jane',
        'last_name' => 'Jones',
    ],
    [
        'id' => 5623,
        'first_name' => 'Peter',
        'last_name' => 'Doe',
    ]
];

$last_names = array_column($records, 'last_name', 'id');
print_r($last_names);

?>


    &example.outputs;


Array
(
    [2135] => Doe
    [3245] => Smith
    [5342] => Jones
    [5623] => Doe
)








     Get the column of usernames from the public "username" property of an
     object



<?php

class User
{
    public $username;

    public function __construct(string $username)
    {
        $this->username = $username;
    }
}

$users = [
    new User('user 1'),
    new User('user 2'),
    new User('user 3'),
];

print_r(array_column($users, 'username'));

?>


    &example.outputs;


Array
(
    [0] => user 1
    [1] => user 2
    [2] => user 3
)








     Get the column of names from the private "name" property of an object
     using the magic methods __isset() and __get()



<?php

class Person
{
    private $name;

    public function __construct(string $name)
    {
        $this->name = $name;
    }

    public function __get($prop)
    {
        return $this->$prop;
    }

    public function __isset($prop) : bool
    {
        return isset($this->$prop);
    }
}

$people = [
    new Person('Fred'),
    new Person('Jane'),
    new Person('John'),
];

print_r(array_column($people, 'name'));
?>


    &example.outputs;


Array
(
    [0] => Fred
    [1] => Jane
    [2] => John
)



   If __isset() is not provided, the object
   contributes no entry to the returned array.
